mod('ecosystem').items.splice(2, 0, J("SQL", T("The language for querying and structuring relational databases.", "لغة الاستعلام عن قواعد البيانات العلائقية وهيكلتها.", "Le langage pour interroger et structurer les bases relationnelles."), TG['Languages']));
